            arg = argv[i]
            if arg == "--":
                out.extend(argv[i:])
                break
            nxt = argv[i + 1] if i + 1 < len(argv) else None
            if (
                arg == "--category"
                and nxt is not None
                and nxt.startswith("-")
                and nxt not in _LIST_OPTIONS
            ):
